import { BASE, NAMES, SCREENS, VISIBLE_SCREENS, SYMBOLS, DEMO_TRADES, storyPlan, scenarioPlan, activePlan, patternLevels, plan, price, demoProfit, escapeHTML as esc } from './core.mjs';
import { icon as oldIcon, fixtures, renderView as fallback, messageHTML, btn, nav } from './ui.mjs';

// Layout, labels and component hierarchy ported from the current SwiftUI views.
// Every price, person, event and outcome below is part of the simulated session,
// except the coach names, photos and specialties, which match the public coaching page.
export function nativeIcon(name, cls='') {
  if(name==='pip') return pipMark(cls);
  if(name==='bolt') return `<svg class="${cls}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M14.5 1 3 14h7l-1 9L21 9h-8Z"/></svg>`;
  if(name==='stop') return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 1h10l6 6v10l-6 6H7l-6-6V7Z" fill="currentColor"/><path d="M7.8 3h8.4l4.8 4.8v8.4L16.2 21H7.8L3 16.2V7.8Z" fill="none" stroke="var(--app-bg)" stroke-width=".8"/></svg>`;
  if(name==='person') return `<svg class="${cls}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2Z"/></svg>`;
  if(name==='more') return `<svg class="${cls}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg>`;
  if(name==='live') return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="2" fill="currentColor"/><path d="M7 7q-4 5 0 10M17 7q4 5 0 10M4 3q-7 9 0 18M20 3q7 9 0 18"/></svg>`;
  if(name==='mountains') return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true"><path d="M1.500 19.500 8.500 7l4.200 7.500 2.300-3.500 7.500 8.500Z"/></svg>`;
  if(name==='people') return `<svg class="${cls}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="8.500" cy="8" r="3.600"/><circle cx="16.800" cy="8.600" r="3"/><path d="M1.500 20c0-4 3-6.400 7-6.400s7 2.400 7 6.400Z"/><path d="M17.200 20h5.300c0-3.400-2.200-5.500-5.700-5.700 1.400 1.400 2.100 3.300 2.100 5.700Z" opacity=".8"/></svg>`;
  if(name==='quiz') return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h16a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H10l-5 4v-4H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z" fill="currentColor"/><path d="M9.500 8.300a2.500 2.500 0 1 1 3.800 2.100c-.9.600-1.300 1-1.300 1.900" fill="none" stroke="var(--app-bg)" stroke-width="1.800" stroke-linecap="round"/><circle cx="12" cy="15" r="1.100" fill="var(--app-bg)"/></svg>`;
  return oldIcon(name,cls);
}
export function pipMark(cls='') {
  return `<svg class="pip-mark ${cls}" viewBox="0 0 200 200" fill="none" aria-hidden="true"><g fill="currentColor"><rect x="66" y="52" width="18" height="16" rx="4"/><rect x="92" y="40" width="18" height="28" rx="4"/><rect x="118" y="26" width="18" height="42" rx="4"/></g><rect x="36" y="76" width="130" height="96" rx="32" stroke="currentColor" stroke-width="14"/><g stroke="currentColor" stroke-width="8" stroke-linecap="round"><path class="pip-eyes" d="M68 124Q80 106 92 124M110 124Q122 106 134 124"/><path d="M78 142Q101 164 124 142"/></g></svg>`;
}
const I=nativeIcon;
const tag=(label,kind='')=>`<span class="n-tag ${kind}">${label}</span>`;
const label=(text,sub='')=>`<div class="n-section"><h3>${text}</h3>${sub?`<span>${sub}</span>`:''}</div>`;
const amount=(n)=>`${n>=0?'+':'−'}$${Math.abs(n).toFixed(2)}`;
const pct=(n)=>`${n>=0?'+':''}${n.toFixed(1)}%`;
const search=(s,placeholder='Analyze any stock, like NVDA',button='Analyze')=>`<form class="n-search" data-form="ticker"><input name="symbol" aria-label="Search sample ticker" placeholder="${placeholder}" maxlength="8" autocomplete="off" value="${esc(s.lookup || '')}"><button type="submit">${button}</button></form>`;
const segment=(values,key,selected,cls='')=>`<div class="n-segment ${cls}" aria-label="${key}">${values.map(v=>btn(v,'set',`data-key="${key}" data-value="${v}" aria-pressed="${selected===v}"`,selected===v?'selected':'')).join('')}</div>`;
const logo=(t)=>`<span class="n-logo logo-${t.toLowerCase()}">${t==='AAPL'?'●':t==='MSFT'?'<i></i><i></i><i></i><i></i>':t==='NVDA'?'◉':t==='TSLA'?'T':t==='META'?'∞':t.slice(0,2)}</span>`;
const mood=(s,p)=>`<video class="n-animal" autoplay muted loop playsinline preload="metadata" aria-label="${p.side==='short'?'Bear':'Bull'} animation from the app" src="assets/app-preview/media/${p.side==='short'?'bear':'bull'}_${p.state==='invalidated'?'asleep':'strong'}${s.dark?'_dark':''}.mp4"></video>`;
const moneyStats=p=>`<div class="n-stats">${[['ENTRY',p.entry,''],['STOP',p.stop,'down'],['TARGET 1',p.target,'up']].map(([t,v,c])=>`<div><small>${t}</small><strong class="${c}">${price(v)}</strong></div>`).join('')}</div>`;
export function nativeChart(s,expanded=false) {
  return `<div class="chart-card n-chart ${s.screen==='stops'?'stop-chart':''}"><div class="chart-wrap"><svg class="candlestick-chart" role="img" aria-label="Interactive simulated candlestick chart. Drag to pan; use plus and minus to zoom." tabindex="0"></svg><div class="chart-data" hidden></div></div><div class="chart-toolbar"><div>${btn('−','zoom-out','aria-label="Zoom chart out"','')}${btn('+','zoom-in','aria-label="Zoom chart in"','')}${btn('‹','pan-back','aria-label="Pan chart earlier"','')}${btn('›','pan-forward','aria-label="Pan chart later"','')}</div><span class="chart-readout">Drag to explore</span><div>${btn('↺','chart-reset','aria-label="Reset chart"','')}${expanded?'':btn(I('expand'),'expand-chart','aria-label="Expand chart"','')}</div></div>${s.screen==='stops'?`<p class="n-chart-hint">tap a line for the why</p>${s.levelInfo?`<div class="n-chart-why">${s.levelInfo==='stop'?'STOP · This is where the sample idea is invalidated.':s.levelInfo==='entry'?'ENTRY · The price used to plan this sample trade.':s.levelInfo==='target2'?'TARGET 2 · Four times the entry-to-stop distance.':'TARGET 1 · Two and a half times the entry-to-stop distance.'}${btn('×','explain-level',`data-value="${s.levelInfo}" aria-label="Close level explanation"`,'')}</div>`:''}`:''}</div>`;
}
export function nativeTitle(s) {
  if(s.detail==='win-compose')return 'Share a win';
  if(s.detail==='milestones')return 'Your milestones';
  if(s.detail==='online')return 'Who is here';
  if(s.detail==='saved')return 'Saved messages';
  if(s.detail==='rooms')return 'Room details';
  if(s.detail==='chart') return `${s.symbol} · ${s.timeframe.toUpperCase()}`;
  if(s.detail==='stock'||s.detail==='setup'||s.detail==='pattern') return '';
  return {home:'Friendly Trader',stream:'Today',macd:'MACD Analyzer',patterns:'Friendly Patterns',screener:'Screener',stops:'Stop Finder',aplus:'A+ Scalps',earnings:'Earnings',economy:'Economy',live:'Live calendar',chat:s.detail==='thread'?'Thread':'Chat',assistant:'Pip',profile:'Settings',course:'Options course',coaching:'Coaching',onboarding:'',menu:s.menuFor==='macd'?'MACD options':'Quick menu'}[s.screen]||'';
}
export function sheetStyle(s) {
  return ['profile','assistant','live'].includes(s.screen)||['setup','stock','pattern','event','chart','share','win-compose','milestones','online','saved','rooms'].includes(s.detail);
}
export function nativeHeader(s) {
  const home=s.screen==='home',sheet=sheetStyle(s),title=nativeTitle(s);
  if(s.screen==='coaching')return coachingHeader(s);
  if(s.screen==='chat'&&!sheet&&s.detail!=='thread')return `<header class="app-header n-header n-chat-header">${btn(I('back'),'home','aria-label="Home"','icon-button n-home')}<h2>Chat</h2>${btn(I('search'),'chat-search-toggle','aria-label="Search messages"','icon-button n-chat-search-button')}${btn(I('more'),'native-menu','data-value="chat" aria-label="Chat options"','icon-button n-more')}</header>`;
  if(s.screen==='onboarding') return `<header class="n-onboard-header">${btn(I('back'),'back','aria-label="Back"','icon-button')}${nav('home','Skip','app-link')}</header>`;
  if(sheet && !title) return `<div class="sheet-handle" aria-hidden="true"></div><button class="n-sheet-close" data-action="back" aria-label="Close detail">${I('close')}</button>`;
  return `${sheet?'<div class="sheet-handle" aria-hidden="true"></div>':''}<header class="app-header n-header ${home?'home-header':''} ${['earnings','economy','screener'].includes(s.screen)?'gold-title':''} ${sheet?'sheet-header':''}">${home?'':btn(I(sheet?'close':'back'),sheet?'back':'home',`aria-label="${sheet?'Close detail':'Home'}"`,'icon-button n-home')}<h2>${title}</h2>${home?`<button class="avatar" data-screen="profile" aria-label="Settings">${s.avatar==='A'?I('person'):esc(s.avatar)}</button>`:s.screen==='chat'?btn(I('more'),'native-menu','data-value="chat" aria-label="Chat options"','icon-button n-more'):''}</header>`;
}
function home(s) {
  const row=(id,symbol,title,line)=>`<button class="n-home-row n-home-live" data-screen="${id}">${I(symbol)}<span><strong>${title}</strong><small>${line}</small></span>${I('next')}</button>`;
  return `<div class="n-home-scene"><button class="n-home-thought" data-screen="stream">Buyers leaning in.</button></div><button class="n-home-today" data-screen="stream">${I('calendar')}<span><small>Today</small><strong>Market’s open.</strong><span class="n-hero-text">NVDA: new MACD BUY cross confirmed on the 15 minute.</span><span class="n-caption">1h ago · MACD</span></span>${I('next')}</button><button class="n-home-tile n-home-wide" data-screen="stops">${I('stop')}<strong>Stop Finder</strong><span><em class="down">Find your exit</em></span></button><div class="n-home-calendars"><button data-screen="earnings">${I('calendar')}<span><strong>Earnings</strong><small>1 reporting today</small></span></button><button data-screen="economy">${I('globe')}<span><strong>Economy</strong><small>CPI Report</small></span></button></div><div class="n-home-grid"><button class="n-home-tile" data-screen="macd">${I('trend')}<strong>MACD</strong><small><b>NVDA</b> <em>BUY</em></small></button><button class="n-home-tile" data-screen="patterns">${I('pulse')}<strong>Patterns</strong><small><b>META</b> <em>Confirmed</em></small></button></div>${row('onboarding','quiz','Trading style quiz','Find your starting point')}${row('course','mountains','Options course','Lesson 1 of 28 · Calls')}${row('coaching','people','Coaching','10 coaches')}<button class="n-home-row" data-screen="chat">${I('chat')}<strong>Chat</strong><small><i class="n-dot"></i> 48 today</small>${I('next')}</button><button class="n-home-row n-home-live" data-screen="live">${I('live')}<span><strong>Live</strong><small>Chart Reading Workshop · 12:00 PM ET</small></span><b class="up">in 1h 18m</b>${I('next')}</button>`;
}
const COURSE=[['Follow along',['Calls','Puts','Strike and date','The price times 100','Sell it back','The most you can lose','Solo: read the alert']],['First trade',['Find the contract','Which strike','Bid and ask','Limit or market','Size to the loss','Solo: first trade']],['Manage it',['A stop on everything','Half at 20%','Stop at your entry','Time decay','Same-day options','Earnings','Solo: manage it']],['Strategies',['The payoff line','A call spread','Covered call','Cash-secured put','A hedge','Straddle','LEAPS','Solo: pick the tool']]];
function course() {
  let number=0;
  return `<p class="n-subtitle">0 of 28 lessons done</p><a class="app-button full" href="https://app.thefriendlytrader.com/learn" target="_blank" rel="noopener">Start lesson 1 ↗</a>${COURSE.map(([level,lessons])=>`${label(level.toUpperCase())}<div class="n-lessons">${lessons.map(title=>`<div class="n-lesson"><b>${++number}</b><span>${title}</span></div>`).join('')}</div>`).join('')}`;
}
// The owner's Coaching page (October 30): one row a coach for the chosen day, a small photo, that coach's times.
// Names, photos and specialties are the public coaching page's; the times are sample data. Josh is prize-only, so he is
// on the Coaches list and not on the calendar. No giveaway row: that stays off the public site while its legal hold stands.
const COACHES=[
  ['josh','Josh','Founder, chart reading, day trading',['Getting started','Chart reading'],[]],
  ['money-mike','Money Mike','Discipline, structure, swing trading',['Swing trading','Risk & discipline'],['8:00 AM','1:00 PM','2:00 PM']],
  ['ms-mary','Ms. Mary','Scalping, Fibonacci, levels and stops',['Scalping','Chart reading'],['4:00 AM','5:00 AM','6:00 AM','9:00 AM','10:00 AM']],
  ['airtuan','AirTuan','Premium selling, covered calls and puts',['Options'],['4:00 AM','6:00 AM','8:00 AM','10:00 AM']],
  ['charles','Charles','Chart clarity, stewardship, patience',['Chart reading','Risk & discipline'],['7:00 AM','9:00 AM','11:00 AM']],
  ['guppy','Turbo Trader Guppy','Entries and exits, risk, psychology',['Risk & discipline','Getting started'],['12:00 PM','1:00 PM','2:00 PM']],
  ['parker','Profits with Parker','Clean setups, live trading, consistency',['Chart reading','Getting started'],['6:30 AM','7:30 AM','8:30 AM']],
  ['tom','Turtle Trader Tom','Watchlists, triggers, risk management',['Swing trading','Risk & discipline'],['5:30 AM','11:00 AM']],
  ['wolf-of-gatsby','Wolf of Gatsby','Mechanical system, indicators, structure',['Chart reading'],['3:00 PM','4:00 PM']],
  ['daniel','Daniel','Trader tools, scalping, Alpha indicator',['Scalping'],['4:30 AM','6:00 AM','12:30 PM']],
].map(([id,name,line,topics,hours])=>({id,name,line,topics,hours}));
const COACH_TOPICS=['All topics','Getting started','Scalping','Swing trading','Options','Chart reading','Risk & discipline'];
const coachPhoto=(c,cls='')=>`<img class="n-coach-photo ${cls}" src="assets/app-preview/media/coaches/${c.id}.jpg" alt="" loading="lazy" decoding="async">`;
const coachOf=s=>String(s.detail||'').startsWith('coach-')?COACHES.find(c=>c.id===s.detail.slice(6)):null;
function coachDays(from=new Date()) {
  return Array.from({length:7},(_,i)=>{
    const d=new Date(from.getFullYear(),from.getMonth(),from.getDate()+i);
    return {index:i,open:d.getDay()!==0,name:i?d.toLocaleDateString('en-US',{weekday:'short'}).toUpperCase():'TODAY',date:d.getDate()};
  });
}
const coachTimes=(c,day)=>c.hours.filter((_,k)=>c.hours.length<3||(k+day)%3!==2);
const coachOnDay=(c,i,day)=>c.hours.length>0&&(i+day)%4!==3;
const coachChips=(c,day)=>`<div class="n-coach-times">${coachTimes(c,day).map(t=>btn(t,'coach-time',`aria-label="${esc(c.name)}, ${t}"`,'n-coach-time')).join('')}</div>`;
function coachZone() {
  try { return new Intl.DateTimeFormat('en-US',{timeZoneName:'long'}).formatToParts(new Date()).find(p=>p.type==='timeZoneName')?.value||'your time zone'; }
  catch { return 'your time zone'; }
}
function coachingCalendar(s) {
  const days=coachDays(),first=days.find(d=>d.open).index,shown=days[s.coachDay??first]?.open?(s.coachDay??first):first;
  const topic=s.coachTopic||'All topics',all=topic==='All topics';
  const rows=COACHES.filter((c,i)=>coachOnDay(c,i,shown)&&(all||c.topics.includes(topic)));
  return `<div class="n-days" role="group" aria-label="Day">${days.map(d=>`<button class="n-day ${d.index===shown?'selected':''}" data-action="coach-day" data-value="${d.index}" aria-pressed="${d.index===shown}" ${d.open?'':'disabled'}><small>${d.name}</small><strong>${d.date}</strong><i></i></button>`).join('')}</div>
  <div class="n-topic-wrap">${btn(`${esc(topic)}<svg viewBox="0 0 12 8" aria-hidden="true"><path d="M1.500 1.500 6 6l4.500-4.500" fill="none" stroke="currentColor" stroke-width="1.800" stroke-linecap="round" stroke-linejoin="round"/></svg>`,'coach-topic-menu',`aria-expanded="${!!s.coachMenu}"`,`n-topic ${all?'':'on'}`)}${s.coachMenu?`<button class="n-topic-scrim" data-action="coach-topic-menu" aria-label="Close topics"></button><div class="n-topic-menu">${COACH_TOPICS.map(t=>btn(t,'coach-topic',`data-value="${esc(t)}" aria-pressed="${t===topic}"`,t===topic?'on':'')).join('')}</div>`:''}</div>
  <p class="n-coach-kind">1-on-1, 1 hr, $200</p>
  ${rows.length?rows.map(c=>`<article class="n-coach-row"><button class="n-coach-who" data-action="native-detail" data-value="coach-${c.id}">${coachPhoto(c)}<strong>${esc(c.name)}</strong>${I('next')}</button>${coachChips(c,shown)}</article>`).join(''):'<p class="n-coach-none">No times this day</p>'}
  <p class="n-coach-zone">Times in ${esc(coachZone())}</p>`;
}
function coachesList() {
  return COACHES.map(c=>`<button class="n-coach-listed" data-action="native-detail" data-value="coach-${c.id}">${coachPhoto(c)}<span><strong>${esc(c.name)}</strong><small>${esc(c.line)}</small></span>${I('next')}</button>`).join('');
}
function coachPage(c) {
  const days=coachDays(),i=COACHES.indexOf(c),next=days.find(d=>d.open&&coachOnDay(c,i,d.index));
  return `<div class="n-coach-page">${coachPhoto(c,'large')}<h3>${esc(c.name)}</h3><p>${esc(c.line)}</p>${next?`<p class="n-coach-kind">1-on-1, 1 hr, $200</p><h4>${next.index?`${next.name[0]}${next.name.slice(1).toLowerCase()} ${next.date}`:'Today'}</h4>${coachChips(c,next.index)}`:''}</div>`;
}
function coaching(s) {
  const coach=coachOf(s);
  return coach?coachPage(coach):s.detail==='coaches'?coachesList():coachingCalendar(s);
}
function coachingHeader(s) {
  const coach=coachOf(s);
  if(coach||s.detail==='coaches')return `<header class="app-header n-header n-coaching-header">${btn(I('back'),'back','aria-label="Back"','icon-button n-home')}<h2>${coach?esc(coach.name):'Coaches'}</h2></header>`;
  return `<header class="app-header n-header n-coaching-header">${btn(I('close'),'home','aria-label="Close Coaching"','icon-button n-home')}<h2>Coaching</h2>${btn('Coaches','native-detail','data-value="coaches"','n-coaches-open')}</header>`;
}
function stream(s) {
 return `<p class="n-subtitle">MARKET OPEN</p><div class="n-now"><div class="n-now-hello">${pipMark()}<div><h3>Morning${s.name==='Alex'?'':', '+esc(s.name)}.</h3><p>Market’s open, and buyers are leaning in.</p></div></div><div class="n-chip-row">${tag('SPY +1.2%','up')}${tag('CPI reported')}</div></div>${label('COMING UP')}<button class="n-stream-row" data-screen="live"><span class="n-time">12:00 PM<br><b>in 1h 18m</b></span><span><strong>Chart Reading Workshop</strong><p>Structure, stops and the next move.</p></span>${I('next')}</button>${label('EARLIER')}<div class="n-stream-list">${[['10:06 AM','NVDA reached its measured move','Patterns · Symmetrical Triangle','patterns'],['9:35 AM','NVDA: new MACD BUY cross confirmed','MACD · on the 15 minute','macd'],['8:30 AM','CPI came in below expectations','Economy · actual 2.8%, expected 2.9%','economy']].map(([time,title,desc,screen])=>`<button class="n-stream-row" data-screen="${screen}"><span class="n-time">${time}</span><span><strong>${title}</strong><p>${desc}</p></span>${I('next')}</button>`).join('')}</div>`;
}
function journey(p) {
 const filled=Math.max(0,Math.min(100,p.progress/Math.abs(p.target-p.entry)*100));
 return `<div class="n-journey ${p.side==='short'?'bear':''} ${p.state==='hit'?'completed':''}"><div class="n-journey-labels"><span>ENTRY ${price(p.entry)}</span><span>TARGET ${price(p.target)}</span></div><div class="n-road"><span class="n-road-best"></span><span class="n-road-fill" style="width:${filled}%"></span><i class="n-entry-dot"></i><i class="n-now-dot" style="left:clamp(8px, ${filled}%, calc(100% - 8px))"></i><span class="n-road-target">${p.state==='hit'?'★':'○'}</span></div><div class="n-road-price">NOW ${price(p.current)}</div></div>`;
}
function storyCard(s,symbol,heading,compact=false) {
 const p=storyPlan(symbol), hit=p.state==='hit';
 return `<article class="n-story-card ${hit?'is-win':''}"><div class="n-card-label"><span>${heading}</span>${tag(hit?'★ COMPLETED':p.state==='invalidated'?'× ENDED':'↗ MOVING',hit?'gold':p.state==='invalidated'?'':'up')}</div><button class="n-story-open" data-action="stock-detail" data-symbol="${symbol}"><div class="n-story-title"><div><div class="n-symbol-side"><strong>${symbol}</strong><b class="${p.side==='short'?'down':'up'}">${p.side==='short'?'SELL':'BUY'}</b>${tag(s.horizon==='Long term'?'1D':s.horizon==='Scalp'?'5M':'15M')}</div><p>Confirmed ${p.at}</p></div>${mood(s,p)}</div>${journey(p)}<p class="n-story-line">${hit?`Reached the ${price(Math.abs(p.target-p.entry))} ${p.side==='short'?'drop':'run'} by ${p.hitAt}. Best move: ${price(p.best)}.`:p.state==='invalidated'?'Closed past the line against the signal. This plan is over.':`Moved ${price(p.progress)} of the usual ${price(Math.abs(p.target-p.entry))} ${p.side==='short'?'drop':'run'} · ${price(Math.max(0,Math.abs(p.target-p.entry)-p.progress))} to go`}</p></button><div class="n-story-footer">${btn('Explore the plan ↗','stock-detail',`data-symbol="${symbol}"`,'app-link')}${btn(I('share'),'share-stock',`data-symbol="${symbol}" aria-label="Share ${symbol} sample plan"`,'icon-button')}</div></article>`;
}
function macd(s) {
 if(s.detail==='stock') return stockDetail(s);
 if(s.detail==='guide') return `<div class="n-reading"><h3>How to read a plan</h3><p>Start at the entry. The marker shows where the latest price sits on the road to the target.</p><p>A gold star means the target was reached. The star stays after a pullback. An ended plan stays in the record too.</p>${moneyStats(storyPlan(s.symbol))}${nav('macd','Back to MACD','app-button full')}</div>`;
 if(s.detail==='watchlist') return `${label('YOUR WATCHLIST')}${s.watchlist.map(t=>stockRow(t,'Saved stock','stock-detail')).join('')}<p class="small-muted">Open a plan and tap its star to update your list.</p>`;
 const line=s.horizon==='Day'?'Trading window · 8 to 11 AM ET':s.horizon==='Scalp'?'Market open · followed until 8 PM ET':'';
 const cards=s.horizon==='Scalp'?`${label('SCALPS · 5 MIN','today')}${storyCard(s,'AMZN','FRESHEST SIGNAL')}${storyCard(s,'META','STILL FOLLOWED')}`:s.horizon==='Long term'?`${label('LONG TERM · DAILY, WEEKLY, MONTHLY','today')}${storyCard(s,'META','LATEST SIGNAL')}${storyCard(s,'AMZN','STILL FOLLOWED')}`:`${label('LIVE TRADES','today')}${storyCard(s,'NVDA','MORNING PLAY')}${storyCard(s,'META','FRESHEST SIGNAL')}`;
 return `${line?`<div class="n-window"><i class="n-dot"></i>${line}</div>`:''}${search(s)}${segment(['Scalp','Day','Long term'],'horizon',s.horizon)}${s.lookup?`${label(s.lookup+' PLANS')}${storyCard(s,s.lookup,'LATEST SIGNAL')}${btn('Clear search','clear-search','','app-link')}`:`${cards}${label('HOW IT WENT','today')}${storyCard(s,'AAPL','TARGET REACHED',true)}${storyCard(s,'MSFT','TARGET REACHED',true)}<details class="n-disclosure"><summary>1 ended plan</summary>${stockRow('GOOGL','Closed past the stop · ended','stock-detail')}</details>`}<details class="n-disclosure"><summary>Your watchlist · ${s.watchlist.length}</summary>${s.watchlist.map(t=>stockRow(t,NAMES[t],'stock-detail')).join('')}</details><details class="n-disclosure"><summary>The Mag 7 board</summary>${SYMBOLS.slice(0,7).map(t=>stockRow(t,NAMES[t],'stock-detail')).join('')}</details>`;
}
