function setup(s) {
 const p=scenarioPlan(s.symbol,s.direction),armed=s.alerts.some(a=>a.symbol===s.symbol&&a.scenario===s.scenario&&a.timeframe===s.timeframe&&a.session===s.session);
 const hit=p.state==='hit';
 return `<div class="n-ticker-header">${logo(s.symbol)}<strong>${s.symbol}</strong>${tag(p.side==='short'?'BEARISH':'BULLISH',p.side==='short'?'down':'up')}<b>${price(p.current)}</b><button class="n-pip-small" data-action="open-pip" aria-label="Ask Pip about this screen">${pipMark()}</button></div>${segment(['1m','2m','5m'],'timeframe',s.timeframe,'timeframes')}<div class="n-scenario-card"><div class="n-scenario-title">${btn(I('bell'),'alert',`aria-label="${armed?'Remove':'Save'} demo alert" aria-pressed="${armed}"`,'icon-button')}<strong>${hit?'IN THE TRADE · TARGET HIT':p.state==='watching'?'LOOKING FOR':p.state==='invalidated'?'HOW IT WENT · OUT':'IN THE TRADE'}</strong></div>${segment(['Breakout','Breakdown','Rejection','Bounce'],'scenario',s.scenario)}<div class="n-target-track"><div class="n-track-labels"><span>${price(p.entry)}</span><span>T1</span><span>T2</span><span>T3</span></div><div class="n-target-line"><span style="width:${Math.max(0,Math.min(100,p.progress/(p.risk*5.5)*100))}%"></span><i></i><i class="${p.best>=p.risk*2.5?'hit':''}">${p.best>=p.risk*2.5?'★':''}</i><i class="${p.best>=p.risk*4?'hit':''}">${p.best>=p.risk*4?'★':''}</i><i></i></div></div><p>${hit?`First target ${price(p.target)} reached. ${p.best>=p.risk*4?'Second target reached too.':'The runner is still on.'}`:p.state==='watching'?`Waiting for a candle close ${p.side==='short'?'below':'above'} ${price(p.entry)}.`:p.state==='invalidated'?`Closed back through ${price(p.stop)}. This plan is out.`:`${p.side==='short'?'Short':'Long'} from ${price(p.entry)} · ${price(Math.max(p.progress,0))} since.`}</p><details class="n-disclosure"><summary>ⓘ How targets work</summary><p>These sample levels show the app’s entry, invalidation and three checkpoints. They are curated teaching levels, not the production engine’s calculations.</p></details></div><div class="n-candle-panel">${label(`${parseInt(s.timeframe)||1} MINUTE CANDLES · TUE, SEP 8`)}${nativeChart(s)}</div>${moneyStats(p)}<div class="detail-actions">${btn('Plan a stop','to-stops')}${btn('Share plan','share','','app-button secondary')}</div>`;
}
// The five stages of the trade, in the app's order (owner, October 30): a setup reaches the board once it has signaled.
const PATTERN_STAGES=['Signal','Confirmed','Retest','Measured move','Failed'];
const stageTone=f=>f.status==='Retest'?'retest':f.status==='Measured move'?'up':f.status==='Failed'?'':f.bias==='Bearish'?'down':'up';
const stageWords=f=>{const way=f.bias==='Bearish'?'Down':'Up';return ({Signal:`${way} signal`,Confirmed:`${way} confirmed`,Retest:`${way} retest held`,'Measured move':`${way} measured move reached`,Failed:`${way} break failed`})[f.status];};
// The road on a setup: what happened, where it stands, what hasn't happened. A failure ends the road.
function patternRoad(f){
 const steps=f.status==='Failed'?['Signal','Confirmed','Failed']:f.candle?['Signal','Confirmed','Measured move']:['Signal','Confirmed','Retest','Measured move'],at=steps.indexOf(f.status);
 const now=f.status==='Measured move'?'Reached':f.status==='Failed'?'Ended':'Now';
 return `<ol class="n-stage-road ${f.bias==='Bearish'?'down':''}">${steps.map((step,i)=>{const state=i===at?'now':i>at?'next':step==='Retest'?'passed':'done';return `<li class="${state} ${step==='Retest'?'retest':step==='Measured move'?'move':step==='Failed'?'failed':''}"><i></i><b>${step}</b><small>${({now,next:'Waiting',passed:'Skipped',done:'Done'})[state]}</small></li>`;}).join('')}</ol>`;
}
// The app's words on its price ladder.
const patternTile=(name,f)=>{const side=f.bias==='Bearish'?'BELOW':'ABOVE';return ({Move:[f.status==='Measured move'?'REACHED':'MEASURED MOVE','up'],Confirm:[`CONFIRM ${side}`,''],Entry:[`CONFIRMED ${side}`,''],Retest:['RETEST','retest'],Fail:['INVALIDATION','down']})[name];};
function patterns(s) {
 if(s.detail==='pattern') {
 const f=fixtures.patterns.find(x=>x.symbol===s.symbol)||fixtures.patterns[0],p=storyPlan(s.symbol);
 const tiles=[['NOW',p.current,''],...patternLevels(f.status,p).filter(([,name])=>name!=='Line').map(([v,name])=>{const [t,c]=patternTile(name,f);return [t,v,c,name];})],finished=f.status==='Measured move'||f.status==='Failed';
 return `<div class="n-pattern-detail-head"><strong>${s.symbol}</strong>${tag(f.status.toUpperCase(),stageTone(f))}${tag('DAILY')}</div><h3 class="n-pattern-name">${f.name}</h3><p class="n-body-copy">${f.text}</p>${patternRoad(f)}${nativeChart(s)}<div class="n-pattern-levels">${tiles.map(([t,v,c,name])=>`<button data-action="explain-level" data-value="${name==='Fail'?'stop':'target'}"><small>${t}</small><strong class="${c}">${price(v)}</strong><span>${pct((v/p.current-1)*100)}</span></button>`).join('')}</div>${s.levelInfo?'<p class="n-demo-note">Invalidation is where this sample is wrong. The measured move is the pattern’s height from the break.</p>':''}<details class="n-disclosure"><summary>Why this shape was identified</summary><p>${f.text} The simulated candles demonstrate the interface; they are not a validated detector result.</p></details>${segment(['Overview','History'],'patternTab',s.patternTab||'Overview')}${s.patternTab==='History'?`<p class="n-demo-note">Illustrative examples, not a backtest.</p>${[['Measured move','up'],['Failed',''],['Expired','']].map(([t,c],i)=>btn(`${tag(t,c)} Example ${i+1}`,'history-example',`data-value="${i}"`,'n-history-example')).join('')}`:''}<div class="detail-actions">${btn('Plan a stop','to-stops',finished?'disabled':'')}${btn('Share setup','share','','app-button secondary')}</div>${finished?'<p class="n-demo-note">Earlier setup. Pick a current one.</p>':''}`;
 }
 const filter=PATTERN_STAGES.includes(s.patternFilter)?s.patternFilter:'All',board=s.patternBoard==='Everything'?'Everything':'Recent';
 const rows=fixtures.patterns.filter(f=>(s.lookup?s.lookup===f.symbol:board==='Everything'||f.recent)&&(filter==='All'||filter===f.status));
 const row=f=>`<button class="n-pattern-row" data-action="pattern-detail" data-symbol="${f.symbol}"><i class="n-dot ${f.bias==='Bearish'?'down':''}"></i><span><strong>${f.symbol}</strong><small>${f.name} · Daily</small></span><b class="${stageTone(f)||'failed'}">${stageWords(f)}</b>${I('next')}</button>`;
 return `<p class="n-subtitle">What’s setting up?</p>${search(s,'Look up a stock or coin','Check')}<p class="n-demo-note">1,000 stocks scanned</p>${segment(['Recent','Everything'],'patternBoard',board)}${segment(['All',...PATTERN_STAGES],'patternFilter',filter,'n-stages')}${PATTERN_STAGES.map(st=>[st,rows.filter(f=>f.status===st)]).filter(([,group])=>group.length).map(([st,group])=>`${label(`${st.toUpperCase()} · ${group.length}`)}${group.map(row).join('')}`).join('')||'<p class="n-demo-note">No setups at this stage in the sample.</p>'}${s.lookup?btn('Clear search','clear-search','','app-link'):''}`;
}
