 if(s.detail==='board') return `${label(s.screenerBoard)}<label class="n-sort">Sort <select data-change="sort" aria-label="Sort screener"><option value="move" ${s.sort==='move'?'selected':''}>Move</option><option value="volume" ${s.sort==='volume'?'selected':''}>Relative volume</option><option value="symbol" ${s.sort==='symbol'?'selected':''}>Ticker</option></select></label>${[...(boards.find(b=>b[0]===s.screenerBoard)?.[2]||SYMBOLS)].sort((a,b)=>s.sort==='symbol'?a.localeCompare(b):s.sort==='volume'?({NVDA:5.8,AAPL:3.7,MSFT:4.1,TSLA:6.2,META:2.8,AMZN:2.1,GOOGL:1.4,SPY:2.3}[b])-({NVDA:5.8,AAPL:3.7,MSFT:4.1,TSLA:6.2,META:2.8,AMZN:2.1,GOOGL:1.4,SPY:2.3}[a]):(BASE[b]/DEMO_TRADES[b].open)-(BASE[a]/DEMO_TRADES[a].open)).map(row).join('')}`;
