 return `<p class="n-subtitle">${type==='earnings'?'Who reports this week.':'The events that move markets.'}</p>${segment(['This week','Reported'],'calendarTab',s.calendarTab)}${type==='economy'&&s.week===0?`<button class="n-econ-feature" data-action="event" data-value="econ-1"><span class="n-eyebrow">TODAY · 8:30 AM ET</span><h3>CPI Report</h3><p>Consumer Price Index</p><div class="n-event-numbers"><span>ACTUAL<strong class="up">2.8%</strong></span><span>EXPECTED<strong>2.9%</strong></span></div><div class="n-market-reaction">SPY <b class="up">+0.54%</b><span>after the release</span></div></button>`:''}<div class="n-week-heading">${btn(I('back'),'week-back',s.week===0?'disabled aria-label="Previous week"':'aria-label="Previous week"','icon-button')}<strong>Week of September ${7+s.week*7}, 2026</strong>${btn(I('next'),'week-forward',s.week===3?'disabled aria-label="Next week"':'aria-label="Next week"','icon-button')}</div>${s.week===0?DAYS.map((day,i)=>{const es=events.filter(e=>e.day===i&&(s.calendarTab!=='Reported'||!['Pending','Upcoming'].includes(e.actual)));if(!es.length)return '';return `<section class="n-day-card ${i===1?'today':''}"><div class="n-day-heading"><strong>${day}${i===1?' · Today':''}</strong><span>Sep ${7+i}</span></div>${es.map(row).join('')}</section>`}).join(''):'<div class="n-empty">No sample events in this week.<br>Return to September 7 to explore the calendar.</div>'}<p class="n-demo-note">Sample schedule · all dates and reports are fictional.</p>`;
