function winCard(w,s) {
 const p=w.symbol?storyPlan(w.symbol):null,entry=w.entry??p?.entry,side=w.side??p?.side,pnl=p?Math.round((w.exit-entry)*(side==='short'?-1:1)*w.quantity*100)/100:0;
 return `<article class="n-win-message"><button class="avatar" data-action="member" data-name="${esc(w.name)}" aria-label="View ${esc(w.name)} demo profile">${esc(w.avatar)}</button><div><div class="n-message-meta"><strong>${esc(w.name)}</strong><time>${w.time}</time></div><div class="n-win-bubble"><span class="n-win-kind">${I(w.kind==='Trade win'?'trend':w.kind==='Followed my plan'?'check':'spark')}${esc(w.kind.toUpperCase())}</span>${p?`<div class="n-trade-win"><div><strong>${w.symbol}</strong>${tag(side==='short'?'SHORT':'LONG','up')}<b class="${pnl>=0?'gold':'down'}">${amount(pnl)}</b></div><div class="n-win-trade-values"><span>Entry<strong>${price(entry)}</strong></span><span>Exit<strong>${price(w.exit)}</strong></span><span>Shares<strong>${w.quantity}</strong></span></div><small>Simulated trade · before fees</small></div>`:''}<p>${esc(w.note)}</p><div class="n-win-reactions">${btn(`${s.reactions.includes(w.id)?'♥':'♡'} Cheer · ${(w.cheers||8)+(s.reactions.includes(w.id)?1:0)}`,'reaction',`data-id="${w.id}" aria-pressed="${s.reactions.includes(w.id)}"`,'')}${tag('Sample win')}</div></div></div></article>`;
}
function wins(s) {
 return `<div class="n-your-wins"><button data-action="milestones"><span>YOUR WINS</span><b>★ 3 of 3 ›</b></button><p>${5+s.wins.length} shared · 5 days · cheered ${5+s.reactions.filter(x=>x.startsWith('w')).length} people</p><div class="n-win-choices">${['Followed my plan','Learned something'].map((k,i)=>btn(`${I(['check','spark'][i])}${k}`,'choose-win',`data-value="${k}"`,'')).join('')}</div></div><div class="n-chat-date">TODAY · SIMULATED COMMUNITY</div>${[...s.wins,...SAMPLE_WINS].filter(w=>!s.search||[w.name,w.note,w.symbol,w.kind].join(' ').toLowerCase().includes(s.search.toLowerCase())).map(w=>winCard(w,s)).join('')}`;
}
function chat(s) {
 if(['share','thread','member'].includes(s.detail))return fallback(s);
 if(s.detail==='online')return `<p class="n-demo-note">Everyone shown here is a fictional preview member.</p>${['Jordan','Casey','Morgan','Riley','Sam','Alex'].map(name=>btn(`<span class="avatar">${name[0]}</span><span><strong>${name}</strong><small>Here today</small></span><i class="n-dot"></i>`,'member',`data-name="${name}"`,'n-setting-row')).join('')}`;
 if(s.detail==='rooms')return fixtures.rooms.map(([t,d,i])=>btn(`${I(i)}<span><strong>${t}</strong><small>${d}</small></span>${I('next')}`,'room',`data-value="${t}"`,'n-setting-row')).join('');
 if(s.detail==='saved')return [...fixtures.messages,...s.messages].filter(m=>s.savedMessages.includes(m.id)).map(m=>messageHTML(m,s)).join('')||'<div class="n-empty">Your saved messages live here.<br>Tap Save on a message to keep it in this preview.</div>';

 if(s.detail==='milestones')return `<div class="n-milestones"><div class="n-medal">★</div><h3>Your progress matters.</h3><p>Three ways you have shown up.</p>${[['First share','You shared a win with the community.'],['Five days of progress','You showed up on five different days.'],['Cheering people on','You celebrated five other traders.']].map(([a,b])=>`<div class="n-milestone"><span>★</span><div><strong>${a}</strong><p>${b}</p></div>${tag('EARNED','gold')}</div>`).join('')}<p class="n-demo-note">Example milestones for this simulated profile.</p>${btn('Back to Wins','back','','app-button full')}</div>`;
 if(s.detail==='win-compose'){const p=storyPlan(s.symbol);return `<h3 class="n-form-title">Share a win</h3>${segment(['Followed my plan','Learned something'],'winKind',s.winKind)}<form data-form="win">${s.winKind==='Trade win'?`<div class="n-win-form-grid"><label class="field">Ticker<select name="symbol" data-change="symbol">${SYMBOLS.map(t=>`<option ${s.symbol===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Direction<select name="side"><option value="long" ${p.side==='long'?'selected':''}>Long</option><option value="short" ${p.side==='short'?'selected':''}>Short</option></select></label><label class="field">Entry ($)<input name="entry" type="number" min="0.01" step="0.01" value="${p.entry.toFixed(2)}" required></label><label class="field">Exit ($)<input name="exit" type="number" min="0.01" step="0.01" value="${p.current.toFixed(2)}" required></label><label class="field">Shares<input name="quantity" type="number" min="1" max="100000" step="1" value="100" required></label></div>`:''}<label class="field">What made this a win?<textarea name="note" rows="4" maxlength="500" required placeholder="The plan, the discipline, the lesson…"></textarea></label><p class="n-demo-note">This creates a simulated post here only.</p><button type="submit" class="app-button full">Share sample win</button></form>`;}
 const tabs=`<div class="n-chat-tabs" role="tablist" aria-label="Chat rooms">${fixtures.rooms.map(([t])=>`<button role="tab" aria-selected="${s.room===t}" data-action="room" data-value="${t}">${t}</button>`).join('')}</div>`;
 const body=s.room==='Wins'?wins(s):fallback({...s,detail:'room'}).replace(/<form class="search-form" data-form="chat-search">.*?<\/form>/,'').replace(`<h3 style="font-size:19px;margin:2px 0 8px">${s.room}</h3>`,'');
 return `${tabs}${s.showChatSearch?`<form class="n-chat-search" data-form="chat-search"><input name="query" aria-label="Search this room" placeholder="Search this room" value="${esc(s.search)}"><button type="submit" aria-label="Search">${I('search')}</button></form>`:''}<div class="n-conversation">${body}</div>`;
}
function assistant(s) {
 return `<div class="n-assistant-brand">${pipMark()}<div><strong>Pip</strong><small>Friendly Assistant</small></div></div><div class="n-pip-bubble"><h3>Hey${s.name?', '+esc(s.name):''}.</h3><p>${s.assistantContext&&s.assistantContext!=='home'?'Let’s make this screen a little clearer.':'Let’s catch you up on the day.'}</p></div><div class="n-pip-prompts">${['What am I looking at?','How do I use the stop?','Does confirmed mean a winning trade?','What should I explore next?'].map(q=>btn(q+' '+I('next'),'ask-pip',`data-value="${q}"`,'')).join('')}</div>${s.pipQuestion?`<p class="n-pip-question">${esc(s.pipQuestion)}</p>`:''}${s.pipAnswer?`<div class="n-pip-bubble" role="status"><p>${esc(s.pipAnswer)}</p></div>`:''}<form class="composer n-pip-composer" data-form="pip"><input name="question" aria-label="Question for Pip" placeholder="Ask Pip…" maxlength="250"><button class="app-button" type="submit">↑</button></form><p class="n-demo-note">Demo answers are prewritten.</p>`;
}
function profile(s) {
 if(['membership','notifications'].includes(s.detail))return fallback(s);
 if(s.detail==='quick-menu')return `<p class="n-body-copy">Choose 3 to 6 tools for your quick menu.</p>${SCREENS.filter(x=>['macd','patterns','stops','chat','stream','earnings','economy'].includes(x[0])).map(([id,t,d,i])=>`<div class="n-setting-row">${I(i)}<span>${t}</span><button class="switch" role="switch" aria-label="${t} shortcut" aria-checked="${s.quick.includes(id)}" data-action="quick-toggle" data-value="${id}"></button>${s.quick.includes(id)?btn('↑','quick-up',`data-value="${id}" aria-label="Move ${t} shortcut earlier"`,'icon-button'):''}</div>`).join('')}`;
 return `<div class="n-profile-identity"><div class="n-profile-avatar">${s.avatar==='A'?I('person'):esc(s.avatar)}<span>★</span></div><strong>FRIENDLY TRADER</strong><div>${btn('Change photo','photo','','app-button secondary')}${btn('Take photo','photo','','app-button secondary')}</div>${s.choosePhoto?`<div class="avatar-choices">${['A','✦','☀','☘'].map(a=>btn(a,'avatar',`data-value="${a}" aria-label="Choose ${a} avatar"`,'')).join('')}</div><p class="n-demo-note">Choose an example avatar in this preview.</p>`:''}</div><form data-form="profile"><label class="field n-name-field">Display name<input name="name" aria-label="Demo display name" value="${esc(s.name)}" minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" required></label><p class="n-demo-note">3–20 letters, numbers or underscores</p><button class="app-button full" type="submit">Save</button></form><div class="n-settings">${[['membership','Membership','Your Friendly Trader access','star'],['notifications','Notifications','Alerts and reminders','bell']].map(([id,t,d,i])=>`<button class="n-setting-row" data-action="profile-detail" data-value="${id}">${I(i)}<span><strong>${t}</strong><small>${d}</small></span>${I('next')}</button>`).join('')}<div class="n-appearance"><strong>Appearance</strong>${segment(['Light','Dark','System'],'profileAppearance',s.profileAppearance)}</div>${s.platform==='macos'?'':`<button class="n-setting-row" data-action="profile-detail" data-value="quick-menu">${I('menu')}<span><strong>Quick menu</strong><small>Choose and reorder your tools</small></span>${I('next')}</button>`}</div>${btn('Reset demo changes','reset','','app-link full')}<p class="n-demo-note">Preview profile · changes last until you reload.</p>`;
}
import { QUIZ } from './native-quiz.mjs';
const PERSONAS={marketNewbie:['The Market Newbie','You\'re new, and your ideas come from tips and headlines.','patterns','Patterns','Real chart patterns, with the price that confirms or breaks each one.'],emotionalRollerCoaster:['The Emotional Roller Coaster','Fear and hope are driving your trades.','macd','MACD','Clear buy and sell signals on the biggest stocks, with the usual move after each.'],riskRoulettePlayer:['The Risk Roulette Player','You risk too much on each trade.','stops','Stop Finder','See where a stop belongs and what a trade can lose before you buy.'],timeCruncher:['The Time Cruncher','You trade between meetings, with no time to watch the market.','stream','Today','Today\'s plays in one scroll, no all-day screen watching.']};
function onboarding(s) {
 if(s.quizStage==='welcome')return `<div class="n-quiz-welcome">${pipMark()}<h3>Trade smarter, free to start</h3><p>Stop Finder, Earnings and Economy are free. Unlock the rest when you're ready.</p>${btn('Take the 60-second quiz','quiz-start','','app-button full')}${nav('home','Open the app','app-button secondary full')}</div>`;
 if(s.quizResult){const [name,line,tool,toolName,reason]=PERSONAS[s.quizResult];return `<div class="n-quiz-result">${pipMark()}<span>Your biggest weakness</span><h3>${name}</h3><p>${line}</p><span>HOW WE FIX IT</span><h4>${toolName}</h4><p>${reason}</p>${nav(tool,tool==='stops'?'Open Stop Finder':'Open the app','app-button full')}${btn('Take it again','quiz-reset','','app-button secondary full')}</div>`;}
 const q=QUIZ[s.quizNode];return `<div class="n-quiz-question"><p>LET’S GET TO KNOW YOU</p><div class="onboarding-progress"><span class="done" style="flex:${s.quizAnswers.length+1}"></span><span style="flex:${Math.max(1,6-s.quizAnswers.length)}"></span></div><h3>${esc(q.prompt)}</h3>${q.answers.map((a,i)=>btn(esc(a.text)+I('next'),'quiz-answer',`data-value="${i}"`,'choice')).join('')}</div>`;
}
function menu(s) {
 if(s.menuFor==='chat')return [['rooms','Room details','list'],['online','Who is here','person'],['notifications','Notifications','bell'],['saved','Saved messages','star'],['profile','Settings','person']].map(([id,t,i])=>btn(`${I(i)}<span>${t}</span>${I('next')}`,'chat-option',`data-value="${id}"`,'n-setting-row')).join('');
 return `${s.platform==='macos'?'':btn('Edit quick menu','edit-quick','','app-button full')}${VISIBLE_SCREENS.map(([id,t,d,i])=>nav(id,`${I(i)}<span><strong>${t}</strong><small>${d}</small></span>${I('next')}`,'n-setting-row')).join('')}`;
}
export function renderNativeView(s) {
 if(s.detail==='chart')return `<div class="chart-expanded">${nativeChart(s,true)}<p class="n-demo-note">Drag to pan · pinch or use + / − to zoom.<br>Arrow keys move through the chart.</p></div>`;
 return ({home,stream,macd,aplus,patterns,screener,stops,course,coaching,earnings:s=>calendar(s,'earnings'),economy:s=>calendar(s,'economy'),live,chat,assistant,profile,onboarding,menu}[s.screen]||home)(s);
}
